        .document {
            max-width: 900px;
            width: 100%;
            padding: 20px;
            box-sizing: border-box;
        }
        /* Header Styles */
        .header {
            display: flex;
            justify-content: space-between;
            align-items: flex-end;
            font-size: 14px;
            font-weight: bold;
            margin-bottom: 5px;
        }
        .header .center {
            font-size: 20px;
            letter-spacing: 2px;
        }
        hr.double-line {
            border: none;
            border-top: 1px solid #000;
            border-bottom: 1px solid #000;
            height: 3px;
            margin: 5px 0 15px 0;
        }
        hr.single-line {
            border: none;
            border-top: 1px solid #000;
            height: 1px;
            margin: 15px 0;
        }
        /* Layout Columns */
        .top-section {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 40px;
        }
        .col {
            display: flex;
            flex-direction: column;
        }
        /* Typography */
        h2.main-title {
            font-size: 16px;
            text-align: center;
            margin: 0 0 10px 0;
            text-transform: uppercase;
            font-weight: bold;
        }
        p.intro {
            font-size: 12px;
            text-align: justify;
            text-indent: 20px;
            margin: 0 0 15px 0;
        }
        h3.section-title {
            font-size: 12px;
            text-align: center;
            margin: 10px 0;
            font-weight: bold;
        }
        /* Leader Line (Dotted list) */
        .leader-line {
            display: flex;
            align-items: flex-end;
            font-size: 11px;
            margin-bottom: 2px;
        }
        .leader-line .name {
            padding-right: 4px;
            background-color: #fcfbf7;
            z-index: 2;
        }
        .leader-line .dots {
            flex-grow: 1;
            border-bottom: 1px dotted #000;
            margin-bottom: 3px;
            min-width: 10px;
        }
        .leader-line .value {
            padding-left: 4px;
            background-color: #fcfbf7;
            z-index: 2;
            text-align: right;
            white-space: nowrap;
        }
        /* Subtotals and Totals */
        .subtotal-container {
            display: flex;
            flex-direction: column;
            align-items: flex-end;
            margin: 5px 0;
        }
        .subtotal-line {
            width: 80px;
            border-top: 1px solid #000;
            margin-bottom: 2px;
        }
        .subtotal-value {
            font-size: 11px;
            font-weight: bold;
            padding-right: 0px;
        }
        .total-section {
            margin-top: 15px;
            display: flex;
            flex-direction: column;
            align-items: flex-end;
        }
        .total-line {
            display: flex;
            justify-content: space-between;
            width: 100%;
            font-size: 12px;
            font-weight: bold;
            border-top: 1px solid #000;
            padding-top: 3px;
            margin-top: 5px;
        }
        .signature-block {
            font-size: 11px;
            text-align: justify;
            margin-top: 20px;
            line-height: 1.3;
        }
        .page-number {
            text-align: right;
            font-size: 11px;
            margin-top: 15px;
        }
        /* Bottom Section */
        .bottom-section-title {
            font-size: 14px;
            text-align: center;
            font-weight: bold;
            margin: 15px 0;
            text-transform: uppercase;
        }
        .bottom-grid {
            display: grid;
            grid-template-columns: 1fr 1fr 1fr;
            gap: 20px;
        }
        .bottom-col {
            font-size: 11px;
        }
        .bottom-col p.intro-text {
            font-size: 11px;
            text-align: justify;
            margin: 0 0 10px 0;
        }
    </style>
</head>
